<?php
require_once __DIR__.'/../includes/auth.php';$data=api_guard('buyer');$pid=safe_int($data['product_id']??0);$uid=(int)user()['id'];if($pid<=0)json_out(['success'=>false,'message'=>'Produto inválido.'],422);$s=db()->prepare('SELECT 1 FROM products WHERE id=?');$s->execute([$pid]);if(!$s->fetchColumn())json_out(['success'=>false,'message'=>'Produto não encontrado.'],422);$s=db()->prepare('SELECT id FROM favorites WHERE user_id=? AND product_id=?');$s->execute([$uid,$pid]);if($s->fetchColumn()){db()->prepare('DELETE FROM favorites WHERE user_id=? AND product_id=?')->execute([$uid,$pid]);json_out(['success'=>true,'saved'=>false,'message'=>'Removido dos favoritos']);}else{db()->prepare('INSERT IGNORE INTO favorites(user_id,product_id) VALUES(?,?)')->execute([$uid,$pid]);json_out(['success'=>true,'saved'=>true,'message'=>'Adicionado aos favoritos']);}
